   467  void DXFImporter::ParseBlocks(DXF::LineReader& reader, DXF::FileData& output) {
   468      while( !reader.End() && !reader.Is(0,"ENDSEC")) {
   469          if (reader.Is(0,"BLOCK")) {
   470              ParseBlock(++reader,output);
   471              continue;
   472          }
   473          ++reader;
   474      }
   475
   476      ASSIMP_LOG_VERBOSE_DEBUG_F("DXF: got ", output.blocks.size()," entries in BLOCKS" );
   477  }
