   479  // ------------------------------------------------------------------------------------------------
   480  void DXFImporter::ParseBlock(DXF::LineReader& reader, DXF::FileData& output) {
   481      // push a new block onto the stack.
   482      output.blocks.push_back( DXF::Block() );
   483      DXF::Block& block = output.blocks.back();
   484
   485      while( !reader.End() && !reader.Is(0,"ENDBLK")) {
   486
   487          switch(reader.GroupCode()) {
   488              case GroupCode_Name:
   489                  block.name = reader.Value();
   490                  break;
   491
   492              case GroupCode_XComp:
   493                  block.base.x = reader.ValueAsFloat();
   494                  break;
   495              case GroupCode_YComp:
   496                  block.base.y = reader.ValueAsFloat();
   497                  break;
   498              case GroupCode_ZComp:
   499                  block.base.z = reader.ValueAsFloat();
   500                  break;
   501          }
   502
   503          if (reader.Is(0,"POLYLINE")) {
   504              ParsePolyLine(++reader,output);
   505              continue;
   506          }
   507
   508          // XXX is this a valid case?
   509          if (reader.Is(0,"INSERT")) {
   510              ASSIMP_LOG_WARN("DXF: INSERT within a BLOCK not currently supported; skipping");
   511              for( ;!reader.End() && !reader.Is(0,"ENDBLK"); ++reader);
   512              break;
   513          }
   514
   515          else if (reader.Is(0,"3DFACE") || reader.Is(0,"LINE") || reader.Is(0,"3DLINE")) {
   516              //http://sourceforge.net/tracker/index.php?func=detail&aid=2970566&group_id=226462&atid=1067632
   517              Parse3DFace(++reader, output);
   518              continue;
   519          }
   520          ++reader;
   521      }
   522  }
