   524  // ------------------------------------------------------------------------------------------------
   525  void DXFImporter::ParseEntities(DXF::LineReader& reader, DXF::FileData& output) {
   526      // Push a new block onto the stack.
   527      output.blocks.push_back( DXF::Block() );
   528      DXF::Block& block = output.blocks.back();
   529
   530      block.name = AI_DXF_ENTITIES_MAGIC_BLOCK;
   531
   532      while( !reader.End() && !reader.Is(0,"ENDSEC")) {
   533          if (reader.Is(0,"POLYLINE")) {
   534              ParsePolyLine(++reader,output);
   535              continue;
   536          }
   537
   538          else if (reader.Is(0,"INSERT")) {
   539              ParseInsertion(++reader,output);
   540              continue;
   541          }
   542
   543          else if (reader.Is(0,"3DFACE") || reader.Is(0,"LINE") || reader.Is(0,"3DLINE")) {
   544              //http://sourceforge.net/tracker/index.php?func=detail&aid=2970566&group_id=226462&atid=1067632
   545              Parse3DFace(++reader, output);
   546              continue;
   547          }
   548
   549          ++reader;
   550      }
   551
   552      ASSIMP_LOG_VERBOSE_DEBUG_F( "DXF: got ", block.lines.size()," polylines and ", block.insertions.size(),
   553          " inserted blocks in ENTITIES" );
   554  }
