   556  void DXFImporter::ParseInsertion(DXF::LineReader& reader, DXF::FileData& output) {
   557      output.blocks.back().insertions.push_back( DXF::InsertBlock() );
   558      DXF::InsertBlock& bl = output.blocks.back().insertions.back();
   559
   560      while( !reader.End() && !reader.Is(0)) {
   561          switch(reader.GroupCode()) {
   562              // name of referenced block
   563          case GroupCode_Name:
   564              bl.name = reader.Value();
   565              break;
   566
   567              // translation
   568          case GroupCode_XComp:
   569              bl.pos.x = reader.ValueAsFloat();
   570              break;
   571          case GroupCode_YComp:
   572              bl.pos.y = reader.ValueAsFloat();
   573              break;
   574          case GroupCode_ZComp:
   575              bl.pos.z = reader.ValueAsFloat();
   576              break;
   577
   578              // scaling
   579          case 41:
   580              bl.scale.x = reader.ValueAsFloat();
   581              break;
   582          case 42:
   583              bl.scale.y = reader.ValueAsFloat();
   584              break;
   585          case 43:
   586              bl.scale.z = reader.ValueAsFloat();
   587              break;
   588
   589              // rotation angle
   590          case 50:
   591              bl.angle = reader.ValueAsFloat();
   592              break;
   593          }
   594          reader++;
   595      }
   596  }
