   603  // ------------------------------------------------------------------------------------------------
   604  void DXFImporter::ParsePolyLine(DXF::LineReader& reader, DXF::FileData& output) {
   605      output.blocks.back().lines.push_back( std::shared_ptr<DXF::PolyLine>( new DXF::PolyLine() ) );
   606      DXF::PolyLine& line = *output.blocks.back().lines.back();
   607
   608      unsigned int iguess = 0, vguess = 0;
   609      while( !reader.End() && !reader.Is(0,"ENDSEC")) {
   610
   611          if (reader.Is(0,"VERTEX")) {
   612              ParsePolyLineVertex(++reader,line);
   613              if (reader.Is(0,"SEQEND")) {
   614                  break;
   615              }
   616              continue;
   617          }
   618
   619          switch(reader.GroupCode())
   620          {
   621          // flags --- important that we know whether it is a
   622          // polyface mesh or 'just' a line.
   623          case 70:
   624              if (!line.flags)    {
   625                  line.flags = reader.ValueAsSignedInt();
   626              }
   627              break;
   628
   629          // optional number of vertices
   630          case 71:
   631              vguess = reader.ValueAsSignedInt();
   632              line.positions.reserve(vguess);
   633              break;
   634
   635          // optional number of faces
   636          case 72:
   637              iguess = reader.ValueAsSignedInt();
   638              line.indices.reserve(iguess);
   639              break;
   640
   641          // 8 specifies the layer on which this line is placed on
   642          case 8:
   643              line.layer = reader.Value();
   644              break;
   645          }
   646
   647          reader++;
   648      }
   649
   650      //if (!(line.flags & DXF_POLYLINE_FLAG_POLYFACEMESH))   {
   651      //  DefaultLogger::get()->warn((Formatter::format("DXF: polyline not currently supported: "),line.flags));
   652      //  output.blocks.back().lines.pop_back();
   653      //  return;
   654      //}
   655
   656      if (vguess && line.positions.size() != vguess) {
   657          ASSIMP_LOG_WARN_F("DXF: unexpected vertex count in polymesh: ",
   658              line.positions.size(),", expected ", vguess );
   659      }
   660
   661      if (line.flags & DXF_POLYLINE_FLAG_POLYFACEMESH ) {
   662          if (line.positions.size() < 3 || line.indices.size() < 3)   {
   663              ASSIMP_LOG_WARN("DXF: not enough vertices for polymesh; ignoring");
   664              output.blocks.back().lines.pop_back();
   665              return;
   666          }
   667
   668          // if these numbers are wrong, parsing might have gone wild.
   669          // however, the docs state that applications are not required
   670          // to set the 71 and 72 fields, respectively, to valid values.
   671          // So just fire a warning.
   672          if (iguess && line.counts.size() != iguess) {
   673              ASSIMP_LOG_WARN_F( "DXF: unexpected face count in polymesh: ", line.counts.size(),", expected ", iguess );
   674          }
   675      }
   676      else if (!line.indices.size() && !line.counts.size()) {
   677          // a poly-line - so there are no indices yet.
   678          size_t guess = line.positions.size() + (line.flags & DXF_POLYLINE_FLAG_CLOSED ? 1 : 0);
   679          line.indices.reserve(guess);
   680
   681          line.counts.reserve(guess/2);
   682          for (unsigned int i = 0; i < line.positions.size()/2; ++i) {
   683              line.indices.push_back(i*2);
   684              line.indices.push_back(i*2+1);
   685              line.counts.push_back(2);
   686          }
   687
   688          // closed polyline?
   689          if (line.flags & DXF_POLYLINE_FLAG_CLOSED) {
   690              line.indices.push_back(static_cast<unsigned int>(line.positions.size()-1));
   691              line.indices.push_back(0);
   692              line.counts.push_back(2);
   693          }
   694      }
   695  }
