   700  // ------------------------------------------------------------------------------------------------
   701  void DXFImporter::ParsePolyLineVertex(DXF::LineReader& reader, DXF::PolyLine& line) {
   702      unsigned int cnti = 0, flags = 0;
   703      unsigned int indices[4];
   704
   705      aiVector3D out;
   706      aiColor4D clr = AI_DXF_DEFAULT_COLOR;
   707
   708      while( !reader.End() ) {
   709
   710          if (reader.Is(0)) { // SEQEND or another VERTEX
   711              break;
   712          }
   713
   714          switch (reader.GroupCode()) {
   715          case 8:
   716                  // layer to which the vertex belongs to - assume that
   717                  // this is always the layer the top-level poly-line
   718                  // entity resides on as well.
   719                  if(reader.Value() != line.layer) {
   720                      ASSIMP_LOG_WARN("DXF: expected vertex to be part of a poly-face but the 0x128 flag isn't set");
   721                  }
   722                  break;
   723
   724          case 70:
   725                  flags = reader.ValueAsUnsignedInt();
   726                  break;
   727
   728          // VERTEX COORDINATES
   729          case GroupCode_XComp:
   730              out.x = reader.ValueAsFloat();
   731              break;
   732
   733          case GroupCode_YComp:
   734              out.y = reader.ValueAsFloat();
   735              break;
   736
   737          case GroupCode_ZComp:
   738              out.z = reader.ValueAsFloat();
   739              break;
   740
   741          // POLYFACE vertex indices
   742          case 71:
   743          case 72:
   744          case 73:
   745          case 74:
   746              if (cnti == 4) {
   747                  ASSIMP_LOG_WARN("DXF: more than 4 indices per face not supported; ignoring");
   748                  break;
   749              }
   750              indices[cnti++] = reader.ValueAsUnsignedInt();
   751              break;
   752
   753          // color
   754          case 62:
   755              clr = g_aclrDxfIndexColors[reader.ValueAsUnsignedInt() % AI_DXF_NUM_INDEX_COLORS];
   756              break;
   757          };
   758
   759          reader++;
   760      }
   761
   762      if (line.flags & DXF_POLYLINE_FLAG_POLYFACEMESH && !(flags & DXF_VERTEX_FLAG_PART_OF_POLYFACE)) {
   763          ASSIMP_LOG_WARN("DXF: expected vertex to be part of a polyface but the 0x128 flag isn't set");
   764      }
   765
   766      if (cnti) {
   767          line.counts.push_back(cnti);
   768          for (unsigned int i = 0; i < cnti; ++i) {
   769              // IMPORTANT NOTE: POLYMESH indices are ONE-BASED
   770              if (indices[i] == 0) {
   771                  ASSIMP_LOG_WARN("DXF: invalid vertex index, indices are one-based.");
   772                  --line.counts.back();
   773                  // Workaround to fix issue 2229
   774                  if (line.counts.back() == 0) {
   775                      line.counts.pop_back();
   776                  }
   777                  continue;
   778              }
   779              line.indices.push_back(indices[i]-1);
   780          }
   781      } else {
   782          line.positions.push_back(out);
   783          line.colors.push_back(clr);
   784      }
   785  }
