   788  void DXFImporter::Parse3DFace(DXF::LineReader& reader, DXF::FileData& output)
   789  {
   790      // (note) this is also used for for parsing line entities, so we
   791      // must handle the vertex_count == 2 case as well.
   792
   793      output.blocks.back().lines.push_back( std::shared_ptr<DXF::PolyLine>( new DXF::PolyLine() )  );
   794      DXF::PolyLine& line = *output.blocks.back().lines.back();
   795
   796      aiVector3D vip[4];
   797      aiColor4D  clr = AI_DXF_DEFAULT_COLOR;
   798
   799      bool b[4] = {false,false,false,false};
   800      while( !reader.End() ) {
   801
   802          // next entity with a groupcode == 0 is probably already the next vertex or polymesh entity
   803          if (reader.GroupCode() == 0) {
   804              break;
   805          }
   806          switch (reader.GroupCode())
   807          {
   808
   809          // 8 specifies the layer
   810          case 8:
   811              line.layer = reader.Value();
   812              break;
   813
   814          // x position of the first corner
   815          case 10:
   816              vip[0].x = reader.ValueAsFloat();
   817              b[2] = true;
   818              break;
   819
   820          // y position of the first corner
   821          case 20:
   822              vip[0].y = reader.ValueAsFloat();
   823              b[2] = true;
   824              break;
   825
   826          // z position of the first corner
   827          case 30:
   828              vip[0].z = reader.ValueAsFloat();
   829              b[2] = true;
   830              break;
   831
   832          // x position of the second corner
   833          case 11:
   834              vip[1].x = reader.ValueAsFloat();
   835              b[3] = true;
   836              break;
   837
   838          // y position of the second corner
   839          case 21:
   840              vip[1].y = reader.ValueAsFloat();
   841              b[3] = true;
   842              break;
   843
   844          // z position of the second corner
   845          case 31:
   846              vip[1].z = reader.ValueAsFloat();
   847              b[3] = true;
   848              break;
   849
   850          // x position of the third corner
   851          case 12:
   852              vip[2].x = reader.ValueAsFloat();
   853              b[0] = true;
   854              break;
   855
   856          // y position of the third corner
   857          case 22:
   858              vip[2].y = reader.ValueAsFloat();
   859              b[0] = true;
   860              break;
   861
   862          // z position of the third corner
   863          case 32:
   864              vip[2].z = reader.ValueAsFloat();
   865              b[0] = true;
   866              break;
   867
   868          // x position of the fourth corner
   869          case 13:
   870              vip[3].x = reader.ValueAsFloat();
   871              b[1] = true;
   872              break;
   873
   874          // y position of the fourth corner
   875          case 23:
   876              vip[3].y = reader.ValueAsFloat();
   877              b[1] = true;
   878              break;
   879
   880          // z position of the fourth corner
   881          case 33:
   882              vip[3].z = reader.ValueAsFloat();
   883              b[1] = true;
   884              break;
   885
   886          // color
   887          case 62:
   888              clr = g_aclrDxfIndexColors[reader.ValueAsUnsignedInt() % AI_DXF_NUM_INDEX_COLORS];
   889              break;
   890          };
   891
   892          ++reader;
   893      }
   894
   895      // the fourth corner may even be identical to the third,
   896      // in this case we treat it as if it didn't exist.
   897      if (vip[3] == vip[2]) {
   898          b[1] = false;
   899      }
   900
   901      // sanity checks to see if we got something meaningful
   902      if ((b[1] && !b[0]) || !b[2] || !b[3]) {
   903          ASSIMP_LOG_WARN("DXF: unexpected vertex setup in 3DFACE/LINE/FACE entity; ignoring");
   904          output.blocks.back().lines.pop_back();
   905          return;
   906      }
   907
   908      const unsigned int cnt = (2+(b[0]?1:0)+(b[1]?1:0));
   909      line.counts.push_back(cnt);
   910
   911      for (unsigned int i = 0; i < cnt; ++i) {
   912          line.indices.push_back(static_cast<unsigned int>(line.positions.size()));
   913          line.positions.push_back(vip[i]);
   914          line.colors.push_back(clr);
   915      }
   916  }
